package com.termux.app.workspace;
import android.app.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowAlertDialog;import java.lang.reflect.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class AgentMenuSeparationTest {
 private void set(Object o,String name,Object value)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}
 private View root(){return ShadowAlertDialog.getLatestAlertDialog().getWindow().getDecorView();}
 private void split(Object ui,String name,WorkspaceStore.Session p)throws Exception{
  Method menu=ui.getClass().getDeclaredMethod(name,WorkspaceStore.Session.class,boolean.class);menu.setAccessible(true);menu.invoke(ui,p,true);assertNotNull(root().findViewWithTag("agent-status-model"));assertNull(root().findViewWithTag("agent-status-permissions"));assertNull(root().findViewWithTag("agent-context-meter"));assertNull(root().findViewWithTag("agent-chat-scale"));ShadowAlertDialog.getLatestAlertDialog().dismiss();
  menu.invoke(ui,p,false);assertNotNull(root().findViewWithTag("agent-context-meter"));assertNull(root().findViewWithTag("agent-status-model"));assertNull(root().findViewWithTag("agent-status-reasoning"));assertNull(root().findViewWithTag("agent-status-permissions"));assertNull(root().findViewWithTag("agent-chat-scale"));ShadowAlertDialog.getLatestAlertDialog().dismiss();
  Method permissions=ui.getClass().getDeclaredMethod("showPermissions",WorkspaceStore.Session.class);permissions.setAccessible(true);permissions.invoke(ui,p);assertNotNull(root().findViewWithTag("agent-status-permissions"));assertNull(root().findViewWithTag("agent-status-model"));assertNull(root().findViewWithTag("agent-context-meter"));ShadowAlertDialog.getLatestAlertDialog().dismiss();
 }
 @Test public void codexModelAndLimitsMenusDoNotContainEachOthersControls()throws Exception{
  com.termux.app.TermuxActivity a=Robolectric.buildActivity(com.termux.app.TermuxActivity.class).get();a.setTheme(com.termux.R.style.Theme_Termux_Black);a.setContentView(com.termux.R.layout.activity_termux);set(a,"mTerminalView",a.findViewById(com.termux.R.id.terminal_view));WorkspaceController controller=new WorkspaceController(a);WorkspaceStore.Session p=new WorkspaceStore.Session();p.environment="codex";p.codexSocketId="synthetic";CodexStatus status=new CodexStatus();status.model="fixture";status.models.put(new JSONObject().put("model","fixture").put("supportedReasoningEfforts",new JSONArray().put("high")));Field f=WorkspaceController.class.getDeclaredField("codexStatuses");f.setAccessible(true);((java.util.Map<String,CodexStatus>)f.get(controller)).put(p.id,status);
  try{Method model=WorkspaceController.class.getDeclaredMethod("showCodexModels",WorkspaceStore.Session.class);model.setAccessible(true);model.invoke(controller,p);assertNotNull(root().findViewWithTag("agent-status-model"));assertNotNull(root().findViewWithTag("agent-status-reasoning"));assertNull(root().findViewWithTag("agent-context-meter"));assertNull(root().findViewWithTag("agent-chat-scale"));ShadowAlertDialog.getLatestAlertDialog().dismiss();Method limits=WorkspaceController.class.getDeclaredMethod("showCodexStatus",WorkspaceStore.Session.class);limits.setAccessible(true);limits.invoke(controller,p);assertNull(root().findViewWithTag("agent-status-model"));assertNull(root().findViewWithTag("agent-status-reasoning"));assertNull(root().findViewWithTag("agent-chat-scale"));assertNotNull(root().findViewWithTag("codex-context-panel"));ShadowAlertDialog.getLatestAlertDialog().dismiss();assertNull(a.getCurrentSession());}finally{controller.close();}
 }
 @Test public void claudeAndGeminiExposeSeparateMenusWithoutStartingModelRequests()throws Exception{
  com.termux.app.TermuxActivity a=Robolectric.buildActivity(com.termux.app.TermuxActivity.class).get();a.setTheme(com.termux.R.style.Theme_Termux_Black);WorkspaceStore.Session p=new WorkspaceStore.Session();p.claudeAgent=true;p.claudeSocketId="fixture";ClaudeLiveUi claude=new ClaudeLiveUi(a,()->p,()->false,(profile,run,model,mode)->{});set(claude,"run","fixture");set(claude,"chip",new TextView(a));set(claude,"status",new JSONObject().put("ready",true).put("state","idle").put("model","native").put("effortOptions",new JSONArray().put("high")));
  try{split(claude,"menu",p);}finally{claude.close();}
  p.claudeAgent=false;p.geminiAgent=true;p.geminiSocketId="fixture";GeminiLiveUi gemini=new GeminiLiveUi(a,()->p,()->false);set(gemini,"run","fixture");set(gemini,"chip",new TextView(a));set(gemini,"status",new GeminiLiveStatus());try{split(gemini,"details",p);}finally{gemini.close();}
 }
 @Test public void openCodeMenusKeepUnknownLimitsAndDoNotMutate()throws Exception{
  Activity a=Robolectric.buildActivity(Activity.class).setup().get();a.setTheme(com.termux.R.style.Theme_Termux_Black);WorkspaceStore.Session p=new WorkspaceStore.Session();p.aiAgent="opencode";
  for(boolean models:new boolean[]{true,false}){java.util.List<String> calls=new java.util.concurrent.CopyOnWriteArrayList<>();OpenCodeStatusUi ui=new OpenCodeStatusUi(a,p,()->fail("mutated"),q->{calls.add(q.optString("op"));return new JSONObject();});if(models)ui.showModels();else ui.showLimits();assertEquals(models,root().findViewWithTag("agent-status-model")!=null);assertNull(root().findViewWithTag("agent-status-permissions"));assertNull(root().findViewWithTag("agent-chat-scale"));for(int i=0;i<20&&calls.isEmpty();i++){Thread.sleep(10);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}assertEquals(models?java.util.Arrays.asList("status","models"):java.util.Collections.singletonList("status"),calls);ShadowAlertDialog.getLatestAlertDialog().dismiss();}a.finish();
 }
}
